function strictDate(string $v):?DateTimeImmutable{if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$v))return null;[$y,$m,$d]=array_map('intval',explode('-',$v));if(!checkdate($m,$d,$y))return null;return new DateTimeImmutable($v.' 00:00:00',new DateTimeZone('America/Cancun'));}
function strictDateTime(string $v):?DateTimeImmutable{if(!preg_match('/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/',$v))return null;$d=DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$v,new DateTimeZone('America/Cancun'));return $d&&$d->format('Y-m-d H:i:s')===$v?$d:null;}
function entityId(mixed $v):int|false{return filter_var($v,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);}
function ensureClient(PDO $pdo,int $id,bool $allowArchived=false):void{$s=$pdo->prepare('SELECT active FROM clients WHERE id=:id');$s->execute(['id'=>$id]);$a=$s->fetchColumn();if($a===false)respond(['error'=>'El cliente no existe'],422);if(!$allowArchived&&(int)$a!==1)respond(['error'=>'El cliente está archivado'],422);}
function serviceDuration(PDO $pdo,int $id,bool $allowInactive=false):int{$s=$pdo->prepare('SELECT active,duration_minutes FROM services WHERE id=:id');$s->execute(['id'=>$id]);$r=$s->fetch();if(!$r)respond(['error'=>'El servicio no existe'],422);if(!$allowInactive&&(int)$r['active']!==1)respond(['error'=>'El servicio está inactivo'],422);return max(5,(int)$r['duration_minutes']);}
function ensureBusinessHours(DateTimeImmutable $start,int $duration):void{$open=new DateTimeImmutable($start->format('Y-m-d').' '.CLIENT_OPEN_TIME,new DateTimeZone('America/Cancun'));$close=new DateTimeImmutable($start->format('Y-m-d').' '.CLIENT_CLOSE_TIME,new DateTimeZone('America/Cancun'));if($start<$open||$start->modify('+'.$duration.' minutes')>$close)respond(['error'=>'Las reservas en línea están disponibles de 8:00 a. m. a 4:00 p. m. y el tratamiento debe terminar antes del cierre.'],422);}
function ensureManager(PDO $pdo,?int $id):void{if($id===null)return;$s=$pdo->prepare("SELECT 1 FROM users WHERE id=:id AND role='operator' AND active=1");$s->execute(['id'=>$id]);if(!$s->fetchColumn())respond(['error'=>'Gestor inválido o inactivo'],422);}
function hasConflict(PDO $pdo,DateTimeImmutable $start,int $duration,?int $managerId,?int $excludeId=null):bool{$end=$start->modify('+'.$duration.' minutes');$sql="SELECT a.id FROM appointments a JOIN services s ON s.id=a.service_id WHERE a.status IN ('pending','confirmed') AND a.starts_at<:end AND DATE_ADD(a.starts_at,INTERVAL s.duration_minutes MINUTE)>:start";$params=['end'=>$end->format('Y-m-d H:i:s'),'start'=>$start->format('Y-m-d H:i:s')];if($managerId!==null){$sql.=' AND (a.manager_user_id=:manager OR a.manager_user_id IS NULL)';$params['manager']=$managerId;}else{$sql.=' AND a.manager_user_id IS NULL';}if($excludeId!==null){$sql.=' AND a.id<>:exclude';$params['exclude']=$excludeId;}$sql.=' LIMIT 1';$s=$pdo->prepare($sql);$s->execute($params);return (bool)$s->fetchColumn();}
function chooseManager(PDO $pdo,DateTimeImmutable $start,int $duration,?int $excludeId=null):?int{$rows=$pdo->query("SELECT id FROM users WHERE role='operator' AND active=1 ORDER BY name")->fetchAll();foreach($rows as $r){$id=(int)$r['id'];if(!hasConflict($pdo,$start,$duration,$id,$excludeId))return $id;}if(!$rows&&!hasConflict($pdo,$start,$duration,null,$excludeId))return null;return -1;}
