 if($isClient){$cid=(int)($user['client_id']??0);if($cid<1)respond(['error'=>'Cuenta sin ficha de cliente'],403);$where[]='a.client_id=:client_id';$params['client_id']=$cid;$clientRaw=(string)$cid;$limit=min($limit,100);}elseif($clientRaw!==''){$cid=entityId($clientRaw);if($cid===false)respond(['error'=>'Cliente inválido'],422);$where[]='a.client_id=:client_id';$params['client_id']=$cid;$limit=min($limit,100);}
 $sql=$select.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY a.starts_at '.($clientRaw!==''?'DESC':'ASC').' LIMIT '.$limit;$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();if($isClient)foreach($rows as &$r){unset($r['notes'],$r['phone']);}respond(['data'=>$rows]);
