 $d=jsonInput();$isClient=$user['role']==='client';if($isClient){requireFields($d,['service_id','starts_at']);$clientId=(int)($user['client_id']??0);if($clientId<1)respond(['error'=>'Cuenta sin ficha de cliente'],403);$status='pending';$notes=null;}else{requirePermission('appointments.create');requireFields($d,['client_id','service_id','starts_at']);$clientId=entityId($d['client_id']);if($clientId===false)respond(['error'=>'Cliente inválido'],422);$status=(string)($d['status']??'pending');if(!in_array($status,['pending','confirmed','completed','cancelled'],true))respond(['error'=>'Estado inválido'],422);$notes=trim((string)($d['notes']??''));}
