 $s=$pdo->prepare('INSERT INTO appointments(client_id,service_id,manager_user_id,starts_at,status,notes) VALUES(:client,:service,:manager,:starts,:status,:notes)');$s->execute(['client'=>$clientId,'service'=>$serviceId,'manager'=>$managerId,'starts'=>$start->format('Y-m-d H:i:s'),'status'=>$status,'notes'=>$notes!==''?$notes:null]);respond(['id'=>(int)$pdo->lastInsertId(),'status'=>$status],201);
