 $isClient=$user['role']==='client';if($isClient){if((int)$cur['client_id']!==(int)($user['client_id']??0))respond(['error'=>'No puedes modificar esta cita'],403);if(!in_array($cur['status'],['pending','confirmed'],true))respond(['error'=>'Esta cita ya no puede modificarse'],409);$oldStart=new DateTimeImmutable((string)$cur['starts_at'],new DateTimeZone('America/Cancun'));if($oldStart<=new DateTimeImmutable('now',new DateTimeZone('America/Cancun')))respond(['error'=>'La cita ya comenzó o pasó'],409);if(($d['action']??'')==='cancel'){$pdo->prepare("UPDATE appointments SET status='cancelled' WHERE id=:id")->execute(['id'=>$id]);respond(['ok'=>true,'status'=>'cancelled']);}$serviceId=isset($d['service_id'])?entityId($d['service_id']):(int)$cur['service_id'];$start=isset($d['starts_at'])?strictDateTime(trim((string)$d['starts_at'])):$oldStart;if($serviceId===false||!$start)respond(['error'=>'Datos inválidos'],422);if($start<=new DateTimeImmutable('now',new DateTimeZone('America/Cancun')))respond(['error'=>'La cita debe ser futura'],422);$duration=serviceDuration($pdo,$serviceId,false);ensureBusinessHours($start,$duration);$managerId=chooseManager($pdo,$start,$duration,$id);if($managerId===-1)respond(['error'=>'Ese horario ya no está disponible'],409);$pdo->prepare("UPDATE appointments SET service_id=:service,manager_user_id=:manager,starts_at=:starts,status='pending' WHERE id=:id")->execute(['service'=>$serviceId,'manager'=>$managerId,'starts'=>$start->format('Y-m-d H:i:s'),'id'=>$id]);respond(['ok'=>true,'status'=>'pending']);}
